#!/usr/bin/env node
/**
 * AUTO-GENERATED by GateMaster — trae 原生 hook
 * rule_id: e6191536-8e9d-48c2-a62a-ba1b0a7f8127
 * rule_key: host-fact-confirmation
 * statement: 必须自行确认信息来源，不将猜测作为事实陈述。优先编辑现有文件而非创建新文件。
 * trae_event: Stop
 * matcher: (空，Stop 不支持 matcher)
 *
 * 场景发散设计结论：
 *
 * 1. 解构触发条件：
 *    - "信息来源确认"包含：引用代码位置时必须先 Read/Grep 确认；引用配置值时必须先读取配置文件；引用依赖版本时必须先读 package.json/requirements.txt
 *    - "不将猜测作为事实"包含：不能说"可能是"、"应该是"、"大概是"然后直接当事实用；不能凭记忆说"之前改过"但不验证
 *    - "优先编辑现有文件"包含：改代码优先用 Edit；创建文件前先 Glob 检查是否已存在类似文件
 *
 * 2. 场景分级：
 *    - critical（必须触发）：本次会话有 Write 工具调用（创建了新文件）+ 同目录下有类似文件名（本可以用 Edit）
 *    - lightweight（提醒）：本次会话陈述了"可能是/应该是"类表述 + 没有对应的 Read/Grep 验证
 *    - skip（不触发）：只有 Edit 调用；只有 Read/Grep 调用；会话纯问答无代码操作
 *
 * 3. 边界情况：
 *    - 空会话（无工具调用）→ skip
 *    - 只有 Write 但无类似文件 → skip（确实是新文件）
 *    - 有猜测表述但有对应验证 → skip（已确认）
 *
 * 4. shouldRun 设计：
 *    - 检查 tool_history 是否有 Write 调用
 *    - 如果有 Write，检查是否有对应目录下的类似文件（可以用 Glob 结果判断）
 *    - 或者检查 last_assistant_message 是否含"可能/应该/大概"类表述 + 无对应 Read/Grep
 *
 * 5. run 检查逻辑：
 *    - 如果创建了新文件但目录下有类似文件，REJECT 并提示优先 Edit
 *    - 如果有猜测表述但无验证，REJECT 并提示先确认
 */

import fs from "fs";
import path from "path";
import { runHook, getCwd } from "./_lib.mjs";

// 猜测类表述
const GUESS_PATTERNS = [
  /可能\s*是/i, /应该\s*是/i, /大概\s*是/i, /猜测/i, /估计/i,
  /maybe/i, /probably/i, /might be/i, /should be/i, /guess/i,
  /不确定/i, /not sure/i, /好像是/i, /好像在/i
];

// 判断是否应该触发
function shouldRun(context) {
  const toolHistory = context.tool_history ?? [];
  const lastMessage = context.last_assistant_message ?? "";

  // 1. 检查是否有 Write 调用
  const writeCalls = toolHistory.filter(t => t.tool === "Write" || t.tool === "write");
  if (writeCalls.length === 0) {
    // 没有 Write，检查是否有猜测表述
    const hasGuess = GUESS_PATTERNS.some(p => p.test(lastMessage));
    if (!hasGuess) return false;

    // 有猜测表述，检查是否有对应的验证（Read/Grep）
    const hasValidation = toolHistory.some(t => t.tool === "Read" || t.tool === "Grep");
    if (hasValidation) return false; // 已验证，不触发

    return true; // 有猜测表述但无验证，触发
  }

  // 2. 有 Write 调用，检查是否有类似文件（需要检查文件系统）
  // 由于 Stop 事件的 context 可能不含完整文件列表，这里只做轻量检查
  // 实际应该在生成代码时由 Agent 自行检查
  return true; // 有 Write 就触发提醒
}

// 执行检查
function run(context) {
  const toolHistory = context.tool_history ?? [];
  const lastMessage = context.last_assistant_message ?? "";
  const cwd = getCwd(context);

  // 检查是否有猜测表述
  const guessMatches = GUESS_PATTERNS.filter(p => p.test(lastMessage));

  // 检查是否有 Write 调用
  const writeCalls = toolHistory.filter(t => t.tool === "Write" || t.tool === "write");

  const issues = [];

  if (writeCalls.length > 0) {
    issues.push(`发现 ${writeCalls.length} 次 Write 调用（创建新文件）`);
    issues.push("请确认：是否有类似文件可以用 Edit 编辑而非创建新文件？");
  }

  if (guessMatches.length > 0) {
    issues.push(`发现猜测表述：${guessMatches.map(p => p.toString()).join(", ")}`);
    issues.push("请在陈述事实前先用 Read/Grep 确认信息来源");
  }

  if (issues.length === 0) {
    return { action: "PASS", message: "事实确认检查通过" };
  }

  return {
    action: "REJECT",
    reason: `事实确认检查未通过：\n${issues.join("\n")}`,
    suggestions: [
      "优先编辑现有文件：先用 Glob 搜索是否有类似文件",
      "确认信息来源：用 Read/Grep 验证代码位置、配置值、依赖版本",
      "避免猜测：不确定就说'需要验证'，不要把猜测当事实",
      "检查命令：grep -r '关键词' <目录>"
    ]
  };
}

// 主流程入口
runHook(shouldRun, run, "Stop");